content.content:
  // The real account, before the first paint of the network. Never during render: the store is a
  // module singleton, and on the server it would be shared between requests (accounts).
  useLayoutEffect(() => {
    const s = useStore.getState();
    s.setReal(initialBuilds);
    useStore.setState({ servers, online, studios, partStudios });
    // Deep link (/dashboard/cyrus/<buildId>): open that mod. Otherwise re-attach to a running build.
    // (read the store AFTER setReal: `s` is the snapshot from before it, so its realBuilds is still empty)
    const fresh = useStore.getState().realBuilds;
    const b = selectedId ? fresh.find((x) => x.id === selectedId) : null;
    if (b) {
      const mod = findMod(realModId(b.rootBuildId ?? b.id));
      if (mod) s.select({ level: "mod", gameId: mod.gameId, category: mod.category, modId: mod.id }, { openPanel: true, focus: "path" });
      // Studios (R1b): /dashboard/cyrus/<id>?tab=assets opens the inspector on the mod's Assets tab
      if (mod && tab === "assets" && studios) s.setPanelTab("assets");
      // Live-test fix (D): a part's fallback (?tab=files&file=..., ?tab=notes) opens that tab, and that file
      else if (mod && tab && tab !== "assets") { s.setPanelTab(tab); if (tab === "files" && file) s.setActiveFile(file); }
      // Creator warning deep link (?retarget=<version>): the next change rebuilds this mod for it.
      if (mod && retarget) {
        useStore.setState((st) => ({ retarget, prefill: { text: `Update this mod for Minecraft ${retarget}: keep every feature and setting, and fix anything the new version changed.`, tick: (st.prefill?.tick ?? 0) + 1 } }));
        s.toast({ tone: "info", title: `Rebuilding for Minecraft ${retarget}`, body: "Your next change is built for that version. Add anything else you want, then send it." });
      }
    }
    // r38 "Create a mod for this server": a new Minecraft mod, prefilled with the server's facts, built for its version
    if (!b && serverContext) {
      if (serverContext.version) useStore.setState({ serverVersion: serverContext.version });
      if (serverContext.version && (MB_VERSIONS as readonly string[]).includes(serverContext.version)) s.setMcVersion(serverContext.version);
      s.select({ level: "category", gameId: "minecraft", category: "gameplay" }, { openPanel: false });
      useStore.setState((st) => ({ prefill: { text: serverPrefill(serverContext), tick: (st.prefill?.tick ?? 0) + 1 } }));
      const notes = serverNotes(serverContext);
      s.toast({ tone: "info", title: `Building for ${serverContext.name}`, body: [`Minecraft ${serverContext.version ?? "latest"}, ${serverContext.plugins.length} plugin(s) already on it.`, ...notes].join(" ") });
    }
    const running = fresh.filter((x) => !isTerminal(x.status)).sort((a, c) => c.createdAt.localeCompare(a.createdAt))[0];
    if (running) void followForge(running.id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // The URL follows the selected real mod (shareable during the preview, like v4).
  const selection = useStore((s) => s.selection);
  const real = useStore((s) => s.real);
  useEffect(() => {
    const id = selection.level === "mod" && selection.modId?.startsWith("nx-") ? real.active[selection.modId] : null;
    const url = id ? `${BASE}/${id}` : BASE;
    if (window.location.pathname !== url) window.history.replaceState(window.history.state, "", url);
  }, [selection, real]);

  // Keep the account fresh: other running builds (two at a time), and everything every 30 s.
  const builds = useStore((s) => s.realBuilds);
  const followed = useStore((s) => (isJobLive(s.job) ? s.job?.buildId : undefined));
  useEffect(() => {
    const ids = builds.filter((b) => !isTerminal(b.status) && b.id !== followed).map((b) => b.id);
    if (!ids.length) return;
    const t = window.setTimeout(async () => {
      const res = await Promise.all(ids.map((id) => fetch(`/api/mod-builder/builds/${id}`, { cache: "no-store" }).then((r) => (r.ok ? r.json() : null)).catch(() => null)));
      const fresh = res.filter(Boolean).map((j) => j.build as ModBuildView);
      if (fresh.length) useStore.getState().upsertReal(fresh);
    }, document.visibilityState === "hidden" ? 9000 : 4000);
    return () => window.clearTimeout(t);
  }, [builds, followed]);
  useEffect(() => {
    const t = window.setInterval(() => void useStore.getState().refreshReal(), 30_000);
    return () => window.clearInterval(t);
  }, []);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const s = useStore.getState();
      const target = e.target as HTMLElement | null;
      const typing = !!target && (target.tagName === "INPUT" || target.tagName === "TEXTAREA" || target.isContentEditable);
      if (document.querySelector(".cy-modal-back")) return; // the token / install modal owns the keys
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
        // Cyrus's own palette wins over the portal's while the studio is open.
        e.preventDefault();
        e.stopImmediatePropagation();
        s.setPaletteOpen(!s.paletteOpen);
        return;
      }
      if (s.paletteOpen || s.addGameOpen) return;
      if (e.key === "Escape") {
        if (typing) {
          // a field that handles its own Esc (e.g. renaming a mod: Esc cancels) keeps it
          if (!target?.closest("[data-esc-own]")) target?.blur();
          return;
        }
        // v6: an expanded panel collapses first, before Esc walks up the network.
        if (s.panelWide && s.panelOpen) s.setPanelWide(false);
        else if (s.selection.level !== "core") s.goUp();
        else if (s.panelOpen) s.setPanelOpen(false);
        return;
      }
      if (typing) return;
      if ((e.key === "e" || e.key === "E") && !e.metaKey && !e.ctrlKey && !e.altKey) {
        e.preventDefault();
        s.setPanelWide(!(s.panelWide && s.panelOpen));
        return;
      }
      if (e.key === "/") {
        e.preventDefault();
        s.focusPrompt();
      }
    };
    // capture: runs before the portal shell's own Ctrl/⌘K listener (bubble, on window)
    window.addEventListener("keydown", onKey, true);
    return () => window.removeEventListener("keydown", onKey, true);
  }, []);

  return (
    <div className="fixed inset-0 overflow-hidden">
      <CosmosBackground />
      <Network />
      <TopBar />
      <ZoomControls />
      <PreviewPanel />
      <PromptDock />
      <CommandPalette />
      <AddGameDialog />
      <ListingDialog />
      <Toasts />
      <CyrusTokensHost />
      <CyrusLibrarySync />
    </div>
  );
}
import { Inter, JetBrains_Mono, Space_Grotesk } from "next/font/google";
import "./cyrus.css";
import "./studio.css";
import { NotificationBell } from "@/components/cyrus/NotificationBell";

// Cyrus v5 typefaces (the handoff's), scoped to the studio: the variables only exist on the
// .cyrus-root wrapper, so the rest of the portal keeps its own fonts.
const inter = Inter({ subsets: ["latin"], variable: "--font-inter", display: "swap" });
const space = Space_Grotesk({ subsets: ["latin"], variable: "--font-space", display: "swap" });
const mono = JetBrains_Mono({ subsets: ["latin"], variable: "--font-jb", display: "swap" });

/**
 * Every Cyrus route renders inside this box: the portal's sidebar and top bar stay, the studio
 * fills the content area (components/nx/Shell.tsx gives /dashboard/cyrus an app frame).
 * `nx-dark-island` opts the studio out of the portal's generated light-mode retargeting: Cyrus
 * has its own deliberate light theme (studio.css), driven by the same portal toggle.
 * The pages themselves call the preview gate (shared.tsx / cores/page.tsx); this layout renders
 * no data.
 */
export default function CyrusLayout({ children }: { children: React.ReactNode }) {
  // r40: the one Cyrus notification bell (fixed, top right of the studio). Not rendered unless CYRUS_NOTIFY=1.
  const bell = process.env.CYRUS_NOTIFY === "1";
  return (
    <div className={`cyrus-root nx-dark-island antialiased ${inter.variable} ${space.variable} ${mono.variable}`}>
      {bell ? <div className="fixed bottom-[7.5rem] left-3 z-40 max-sm:bottom-[5.25rem] max-sm:left-auto max-sm:right-[4.75rem]"><NotificationBell /></div> : null}
      {children}
    </div>
  );
}
import type { Metadata } from "next";
import { CyrusPage, cyrusMetadata } from "./shared";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return cyrusMetadata();
}

/**
 * Cyrus: the AI mod studio (v5, the owner's redesign, 2026-10-08; styles in ./layout.tsx).
 * PRIVATE PREVIEW behind the same gate as /dashboard/mod-builder:
 * requireModBuilderUser() 404s everyone outside lib/preview-access.ts "modbuilder".
 */
export default async function CyrusHome({ searchParams }: { searchParams: Promise<{ server?: string }> }) {
  const sp = await searchParams;
  return CyrusPage(null, { server: typeof sp.server === "string" ? sp.server : null });
}

import { redirect } from "next/navigation";
import { headers } from "next/headers";
import { currentUser } from "@/lib/auth";
import { bridgeConfig } from "@/lib/cyrus/bridge/config";
import { safeCyrusNext } from "@/lib/cyrus/bridge/routing";
import { CyrusHostProvider } from "./HostContext";
import { CyrusWordmark } from "@/components/cyrus/brand/CyrusBrand";
import { CyrusTokenChip } from "@/components/cyrus-tokens";
import { ConsentBanner } from "@/components/cyrus/ConsentBanner";
import { attributionEnabled, consentEnabled } from "@/lib/cyrus/analytics/consent";

/**
 * The Cyrus-host (cyrus.my) chrome: Cyrus' own brand bar around the SAME studio pages Nxeon serves at
 * /dashboard/cyrus (no copied components). Chosen by app/dashboard/layout.tsx when middleware marked the request as
 * Cyrus-host (CYRUS_DOMAIN_MODE). Signed-out visitors go to the Cyrus sign-in, which delegates to the Nxeon identity.
 */
export async function CyrusHostShell({ children }: { children: React.ReactNode }) {
  const user = await currentUser();
  if (!user) {
    const h = await headers();
    const next = safeCyrusNext(`${h.get("x-pathname") ?? "/studio"}${h.get("x-search") ?? ""}`);
    redirect(`/sign-in?next=${encodeURIComponent(next)}`);
  }
  const nxeon = bridgeConfig().nxeonOrigin;
  return (
    <div className="cyrus-host flex h-dvh flex-col bg-[#05060a] text-white">
      <header className="nx-dark-island flex h-12 shrink-0 items-center gap-2 border-b border-white/10 bg-[#05060a] px-3 text-white sm:gap-4 sm:px-4">
        <a href="/studio" aria-label="Cyrus studio"><CyrusWordmark height={20} /></a>
        <span className="hidden text-xs text-white/50 sm:inline">A Nxeon product</span>
        <div className="ml-auto flex items-center gap-2 whitespace-nowrap text-[13px] sm:gap-3 sm:text-sm">
          <CyrusTokenChip compact beta={false} />
          <a className="text-white/70 hover:text-white" href="/servers"><span className="sm:hidden">Servers</span><span className="hidden sm:inline">My servers</span></a>
          <a className="text-white/70 hover:text-white" href="/wallet">Wallet</a>
          <span className="hidden text-white/50 sm:inline">{user.name || user.email}</span>
          {/* the one way back: Cyrus pages never repeat it */}
          <a className="hidden text-white/50 hover:text-white md:inline" href={nxeon} target="_blank" rel="noopener noreferrer">Back to Nxeon</a>
          <form method="post" action="/auth/logout"><button className="text-white/70 hover:text-white" type="submit">Sign out</button></form>
        </div>
      </header>
      <main className="min-h-0 flex-1"><CyrusHostProvider value={{ onCyrus: true, nxeon }}>{children}</CyrusHostProvider></main>
      {/* r40: cyrus.my cookie consent (off unless CYRUS_CONSENT=1) */}
      {consentEnabled(process.env) ? <ConsentBanner attribution={attributionEnabled(process.env)} /> : null}
    </div>
  );
}
"use client";
// Tells client components whether they render inside the Cyrus host (cyrus.my) so they can keep people there:
// native pages (/servers, /wallet) on cyrus.my, the Nxeon pages (new tab, labelled "on Nxeon") otherwise.
// Provided by CyrusHostShell; the default is the Nxeon portal (relative links, same tab).
import { createContext, useContext } from "react";

export type CyrusHostInfo = { onCyrus: boolean; nxeon: string };
const Ctx = createContext<CyrusHostInfo>({ onCyrus: false, nxeon: "" });

export function CyrusHostProvider({ value, children }: { value: CyrusHostInfo; children: React.ReactNode }) {
  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}
export const useCyrusHostInfo = () => useContext(Ctx);

export type LinkSpec = { href: string; external: boolean; target?: "_blank"; rel?: string };
const EXT = { target: "_blank", rel: "noopener noreferrer" } as const;

/** The server's mods: native /servers on cyrus.my, the Mods tab of the Nxeon server page elsewhere. */
export function serverModsLink(h: CyrusHostInfo, serverId: string): LinkSpec {
  return h.onCyrus ? { href: `/servers#s-${encodeURIComponent(serverId)}`, external: false } : { href: `/dashboard/servers/${serverId}?tab=mods`, external: false };
}
/** Buying a game server only exists on Nxeon: on cyrus.my it opens there in a new tab. */
export function getServerLink(h: CyrusHostInfo): LinkSpec {
  return h.onCyrus ? { href: `${h.nxeon}/dashboard/deploy`, external: true, ...EXT } : { href: "/dashboard/deploy", external: false };
}
import "./app.css";
import { CyrusWordmark } from "@/components/cyrus/brand/CyrusBrand";
import { CyrusTokenChip, CyrusTokensHost } from "@/components/cyrus-tokens";
import { AppNav } from "@/components/cyrus/app/AppNav";
import { appViewer, P } from "./_gate";

export const dynamic = "force-dynamic";

/**
 * Cyrus customer app shell (r39): the landing's language for every customer page (rail + glass + energy accents),
 * inside the Cyrus layout (fonts, .cyrus-root). On cyrus.my the host bar sits above it; in the Nxeon portal the
 * portal frame does. 404 unless the app switch and the studio gate both allow the viewer (see ./_gate.ts).
 */
export default async function CyrusAppLayout({ children }: { children: React.ReactNode }) {
  const v = await appViewer();
  const hrefs = { home: v.href(P.home), new: v.href(P.new), projects: v.href(P.projects), assets: v.href(P.assets), servers: v.href(P.servers), wallet: v.href(P.wallet), studio: v.onCyrus ? "/studio" : "/dashboard/cyrus", account: v.href(P.account) };
  return (
    <div className="cx-app">
      <div className="cx-aura" aria-hidden="true" />
      <div className="cx-shell">
        <aside className="cx-rail">
          <a className="cx-brand" href={hrefs.home} aria-label="Cyrus App home"><CyrusWordmark height={18} /><small>App</small></a>
          <AppNav hrefs={hrefs} />
          <div className="cx-rail-foot">
            <CyrusTokenChip compact beta={false} />
            <span className="cx-who" title={v.user.email ?? ""}>{v.user.name || v.user.email}</span>
          </div>
        </aside>
        {/* not a second <main>: the portal / Cyrus host shell already provides the page's main landmark (r49 a11y) */}
        <div className="cx-main" id="cx-main">
          {/* Simple (this app: one prompt, then install) / Studio (every studio, chat, attachments). Same account and projects. */}
          <div className="cx-modebar"><div className="cx-seg" role="group" aria-label="View"><a href={hrefs.home} aria-current="page">Simple</a><a href={hrefs.studio}>Studio</a></div></div>
          <div className="cx-page">{children}</div>
        </div>
      </div>
      <CyrusTokensHost />
    </div>
  );
}
/* Cyrus customer app (r39): the landing's language (black and white, crisp type, electric blue + violet energy,
   glass panels) for every customer page. Everything is scoped to .cx-app and prefixed cx- (no Tailwind collisions).
   Dark is the default; html[data-theme="light"] (the portal toggle) gets a real light theme. */
.cx-app {
  --cx-bg: #000; --cx-bg-2: #06070c; --cx-ink: #fff; --cx-ink-2: rgba(255,255,255,.74); --cx-ink-3: rgba(255,255,255,.56); --cx-ink-4: rgba(255,255,255,.36);
  --cx-line: rgba(255,255,255,.09); --cx-line-2: rgba(255,255,255,.16);
  --cx-blue: #3d7bff; --cx-blue-hi: #79a6ff; --cx-violet: #8b5cff; --cx-violet-hi: #b49bff;
  --cx-ok: #4ade9a; --cx-bad: #ff6b81; --cx-warn: #ffc56b;
  --cx-glass: linear-gradient(180deg, rgba(255,255,255,.05), rgba(255,255,255,.015)); --cx-glass-2: rgba(255,255,255,.06);
  --cx-energy: linear-gradient(100deg, var(--cx-blue), var(--cx-violet));
  --cx-display: var(--font-space), "Space Grotesk", var(--font-inter), system-ui, sans-serif;
  --cx-body: var(--font-inter), Inter, system-ui, sans-serif; --cx-mono: var(--font-jb), ui-monospace, monospace;
  --cx-r: 18px; --cx-r-sm: 12px;
  color-scheme: dark; background: var(--cx-bg); color: var(--cx-ink); font: 14.5px/1.55 var(--cx-body); -webkit-font-smoothing: antialiased;
  min-height: 100%; position: relative; isolation: isolate;
}
html[data-theme="light"] .cx-app {
  --cx-bg: #f6f7fb; --cx-bg-2: #ffffff; --cx-ink: #07080d; --cx-ink-2: rgba(7,8,13,.76); --cx-ink-3: rgba(7,8,13,.58); --cx-ink-4: rgba(7,8,13,.4);
  --cx-line: rgba(7,8,13,.09); --cx-line-2: rgba(7,8,13,.16); --cx-blue: #2459e0; --cx-blue-hi: #2459e0; --cx-violet: #6a3df0; --cx-violet-hi: #6a3df0;
  --cx-ok: #12865a; --cx-bad: #c8243f; --cx-warn: #9a5b00;
  --cx-glass: linear-gradient(180deg, #fff, #fbfbfe); --cx-glass-2: rgba(7,8,13,.04); color-scheme: light;
}
.cx-app *, .cx-app *::before, .cx-app *::after { box-sizing: border-box; }
:where(.cx-app) a { color: inherit; text-decoration: none; }
.cx-app :focus-visible { outline: 2px solid var(--cx-blue-hi); outline-offset: 3px; border-radius: 8px; }
.cx-app ::selection { background: var(--cx-violet); color: #fff; }

/* ambient energy behind the content (no motion when reduced) */
.cx-aura { position: absolute; inset: 0; z-index: -1; pointer-events: none; overflow: hidden; }
.cx-aura::before, .cx-aura::after { content: ""; position: absolute; width: 60vmax; height: 60vmax; border-radius: 50%; filter: blur(80px); opacity: .16; animation: cx-drift 26s ease-in-out infinite alternate; }
.cx-aura::before { background: radial-gradient(circle, var(--cx-blue), transparent 62%); top: -30vmax; right: -14vmax; }
.cx-aura::after { background: radial-gradient(circle, var(--cx-violet), transparent 62%); bottom: -36vmax; left: -18vmax; animation-delay: -9s; }
html[data-theme="light"] .cx-app .cx-aura::before, html[data-theme="light"] .cx-app .cx-aura::after { opacity: .07; }
@keyframes cx-drift { to { transform: translate3d(4vmax, 3vmax, 0) scale(1.08); } }

/* ---------- shell ---------- */
.cx-shell { display: grid; grid-template-columns: 232px minmax(0, 1fr); min-height: 100%; }
.cx-rail { position: sticky; top: 0; align-self: start; height: 100dvh; max-height: 100%; display: flex; flex-direction: column; gap: 4px; padding: 20px 14px; border-right: 1px solid var(--cx-line); background: color-mix(in srgb, var(--cx-bg) 70%, transparent); backdrop-filter: blur(18px) saturate(140%); -webkit-backdrop-filter: blur(18px) saturate(140%); }
.cx-brand { display: flex; align-items: center; gap: 10px; padding: 4px 10px 18px; }
.cx-brand small { font: 500 10px var(--cx-mono); letter-spacing: .18em; text-transform: uppercase; color: var(--cx-ink-3); }
.cx-nav-a { display: flex; align-items: center; gap: 11px; padding: 9px 11px; border-radius: 11px; color: var(--cx-ink-3); font-weight: 500; transition: background .2s, color .2s; position: relative; }
.cx-nav-a svg { width: 17px; height: 17px; flex: none; }
.cx-nav-a:hover { color: var(--cx-ink); background: var(--cx-glass-2); }
.cx-nav-a[aria-current="page"] { color: var(--cx-ink); background: var(--cx-glass-2); box-shadow: inset 0 0 0 1px var(--cx-line-2); }
.cx-nav-a[aria-current="page"]::before { content: ""; position: absolute; left: -14px; top: 9px; bottom: 9px; width: 2px; border-radius: 2px; background: var(--cx-energy); }
.cx-nav-sep { height: 1px; background: var(--cx-line); margin: 10px 8px; }
.cx-rail-foot { margin-top: auto; display: grid; gap: 10px; padding: 10px; border-top: 1px solid var(--cx-line); }
.cx-rail-foot .cx-who { font-size: 12.5px; color: var(--cx-ink-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cx-main { min-width: 0; padding: 28px clamp(16px, 3.4vw, 44px) 64px; }
.cx-page { max-width: 1180px; margin: 0 auto; }

/* ---------- type ---------- */
.cx-eyebrow { font: 500 10.5px var(--cx-mono); letter-spacing: .2em; text-transform: uppercase; color: var(--cx-ink-4); }
.cx-h1 { font: 600 clamp(26px, 3.2vw, 36px)/1.08 var(--cx-display); letter-spacing: -.02em; margin: 6px 0 0; }
.cx-h2 { font: 600 17px/1.2 var(--cx-display); letter-spacing: -.01em; margin: 0; }
.cx-sub { color: var(--cx-ink-3); margin: 8px 0 0; max-width: 64ch; }
.cx-mono { font-family: var(--cx-mono); font-size: 12px; letter-spacing: .02em; }
.cx-muted { color: var(--cx-ink-3); }
.cx-faint { color: var(--cx-ink-4); }
.cx-grad { background: var(--cx-energy); -webkit-background-clip: text; background-clip: text; color: transparent; }
.cx-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-bottom: 22px; }

/* ---------- glass cards ---------- */
.cx-card { position: relative; border-radius: var(--cx-r); background: var(--cx-glass); border: 1px solid var(--cx-line); padding: 18px; overflow: hidden; }
html[data-theme="light"] .cx-app .cx-card { box-shadow: 0 1px 0 rgba(7,8,13,.03), 0 8px 24px -16px rgba(7,8,13,.18); }
.cx-card-h { display: flex; align-items: center; gap: 10px; margin-bottom: 14px; }
.cx-card-h .cx-aside { margin-left: auto; font: 500 11px var(--cx-mono); color: var(--cx-ink-4); }
.cx-glyph { width: 32px; height: 32px; border-radius: 10px; display: grid; place-items: center; border: 1px solid var(--cx-line-2); background: var(--cx-glass-2); flex: none; }
.cx-glyph svg { width: 16px; height: 16px; }
.cx-grid { display: grid; gap: 14px; grid-template-columns: repeat(12, minmax(0, 1fr)); }
.cx-s4 { grid-column: span 4; } .cx-s5 { grid-column: span 5; } .cx-s6 { grid-column: span 6; } .cx-s7 { grid-column: span 7; } .cx-s8 { grid-column: span 8; } .cx-s12 { grid-column: span 12; }
.cx-reveal { animation: cx-in .5s cubic-bezier(.2,.8,.2,1) both; animation-delay: var(--d, 0s); }
@keyframes cx-in { from { opacity: 0; transform: translateY(8px); } }

/* ---------- controls ---------- */
.cx-btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; height: 38px; padding: 0 16px; border-radius: 999px; border: 1px solid var(--cx-line-2); background: transparent; color: var(--cx-ink); font: 600 13.5px var(--cx-body); cursor: pointer; transition: background .2s, border-color .2s, transform .2s, opacity .2s; white-space: nowrap; }
.cx-btn:hover { background: var(--cx-glass-2); border-color: var(--cx-ink-4); }
.cx-btn:active { transform: translateY(1px); }
.cx-btn[disabled], .cx-btn[aria-disabled="true"] { opacity: .45; cursor: not-allowed; }
.cx-btn-pri { background: var(--cx-ink); color: var(--cx-bg); border-color: transparent; }
.cx-btn-pri:hover { background: var(--cx-ink); opacity: .9; }
