  // The internal tree is the rewrite target of the public auth paths (Next may run middleware again on it): on the
  // Cyrus host it is just another name for them. Off the Cyrus host middleware 404s it, and its pages/handlers
  // refuse to render without the marker this middleware alone sets.
  if (under(p, CYRUS_HOST_TREE)) return { kind: "pass" };
  if (p.startsWith("/_next/") || p === "/favicon.ico" || p.startsWith("/.well-known/") || p.startsWith("/vendor/") || isStaticFilePath(p)) return { kind: "pass" };
