"use client";

import { Fragment, useMemo } from "react";
import { CategoryIcon } from "@/components/cyrus/icons/CategoryIcons";
import { CyrusGlyph } from "@/components/cyrus/icons/CyrusLogo";
import { GameEmblem } from "@/components/cyrus/icons/GameEmblems";
import { CyrusWordmark } from "@/components/cyrus/brand/CyrusBrand";
import { ChevronRightIcon, PanelRightIcon, PlusIcon, SearchIcon } from "@/components/cyrus/icons/ui";
import { CATEGORY_BY_KEY, MAX_GAMES } from "@/lib/cyrus/data";
import { canAddGame } from "@/lib/cyrus/ring";
import { useGame, useGames, useMod, useStore } from "@/lib/cyrus/store";
import { CyrusTokenChip } from "@/components/cyrus-tokens";
import { SoundToggle } from "@/components/cyrus/brand/SoundToggle";

function Crumb({ onClick, active, children, rgb, label }: { onClick: () => void; active: boolean; children: React.ReactNode; rgb?: string; label?: string }) {
  return (
    <button
      type="button"
      onClick={onClick}
      aria-label={label}
      className={`tint flex min-w-0 items-center gap-1.5 rounded-lg px-2 py-1 text-[12.5px] transition ${
        active ? "bg-[rgb(var(--glow)/0.12)] font-medium text-cy-ink" : "text-cy-muted hover:bg-[rgb(var(--glow)/0.07)] hover:text-cy-ink"
      }`}
      style={rgb ? { ["--c" as string]: rgb } : undefined}
    >
      {children}
    </button>
  );
}

export function TopBar() {
  const selection = useStore((s) => s.selection);
  const select = useStore((s) => s.select);
  const setPaletteOpen = useStore((s) => s.setPaletteOpen);
  const setAddGameOpen = useStore((s) => s.setAddGameOpen);
  const panelOpen = useStore((s) => s.panelOpen);
  const setPanelOpen = useStore((s) => s.setPanelOpen);
  const mod = useMod(selection.modId);
  const games = useGames();
  const addable = useMemo(() => canAddGame(games, undefined, undefined, MAX_GAMES), [games]);
  const game = useGame(selection.gameId);
  const cat = selection.category ? CATEGORY_BY_KEY[selection.category] : undefined;

  const crumbs = [
    <Crumb key="core" label="Cyrus Core" active={selection.level === "core"} onClick={() => select({ level: "core" })}>
      <span className="h-2.5 w-2.5 rounded-full bg-gradient-to-br from-white via-cy-accent to-cy-cyan shadow-[0_0_8px_var(--accent)]" />
      <span className="hidden sm:inline">Core</span>
    </Crumb>,
  ];
  if (game)
    crumbs.push(
      <Crumb key="g" rgb={game.rgb} active={selection.level === "game"} onClick={() => select({ level: "game", gameId: game.id })}>
        <span className="text-[14px]" style={{ color: "var(--cc)" }}>
          <GameEmblem emblem={game.emblem} logo={game.logo} logoTone={game.logoTone} />
        </span>
        <span className="truncate">{game.short}</span>
      </Crumb>,
    );
  if (game && cat)
    crumbs.push(
      <Crumb key="c" rgb={cat.rgb} active={selection.level === "category"} onClick={() => select({ level: "category", gameId: game.id, category: cat.key })}>
        <span className="text-[14px]" style={{ color: "var(--cc)" }}>
          <CategoryIcon k={cat.key} />
        </span>
        <span className="truncate">{cat.label}</span>
      </Crumb>,
    );
  if (mod && cat)
    crumbs.push(
      <Crumb key="m" rgb={cat.rgb} active onClick={() => select({ level: "mod", gameId: mod.gameId, category: mod.category, modId: mod.id }, { openPanel: true })}>
        <span className="h-2 w-2 rounded-full" style={{ background: `rgb(${cat.rgb})`, boxShadow: `0 0 8px rgb(${cat.rgb})` }} />
        <span className="max-w-[180px] truncate">{mod.name}</span>
      </Crumb>,
    );

  return (
    <header className="pointer-events-none fixed inset-x-0 top-0 z-40 flex h-16 items-center gap-3 px-3 md:px-5">
      <button type="button" onClick={() => select({ level: "core" })} className="pointer-events-auto flex shrink-0 items-center gap-2.5" aria-label="Cyrus Mod Forge home">
        {/* the owner's marks: the SVG Y on phones, the wordmark (white on dark, black + gradient Y on light) above */}
        <CyrusGlyph id="topbar-logo" className="topbar-logo text-[24px] sm:hidden" />
        <span className="hidden flex-col leading-none sm:flex">
          <CyrusWordmark height={19} className="topbar-logo" />
          <span className="mt-1 text-[8px] font-semibold uppercase tracking-[0.36em] text-cy-muted">Mod Forge</span>
        </span>
      </button>

      <nav aria-label="Location" className="glass-soft pointer-events-auto ml-1 flex min-w-0 items-center gap-0.5 rounded-xl p-1 md:ml-4">
        {crumbs.map((c, i) => (
          <Fragment key={i}>
            {i > 0 && <ChevronRightIcon className="shrink-0 text-[11px] text-cy-faint" />}
            {c}
          </Fragment>
        ))}
      </nav>

      <div className="pointer-events-auto ml-auto flex shrink-0 items-center gap-1.5">
        {/* v6: only while a supported game can still join the ring (lib/cyrus/ring.ts); the core gallery button is gone */}
        {addable && (
          <button
            type="button"
            onClick={() => setAddGameOpen(true)}
            className="glass-soft flex h-9 items-center gap-1.5 rounded-xl px-3 text-[12.5px] font-medium text-cy-ink-2 transition hover:border-cy-line-2 hover:text-cy-ink"
            title="Add a supported game to the network"
          >
            <PlusIcon />
            <span className="hidden sm:inline">Add game</span>
          </button>
        )}
        <button
          type="button"
          onClick={() => setPaletteOpen(true)}
          className="glass-soft hidden h-9 items-center gap-2 rounded-xl px-3 text-[12.5px] text-cy-muted transition hover:text-cy-ink md:flex"
        >
          <SearchIcon />
          Jump to…
          <span className="cy5-kbd ml-3">Ctrl K</span>
        </button>
        <button type="button" onClick={() => setPaletteOpen(true)} className="glass-soft grid h-9 w-9 place-items-center rounded-xl text-cy-ink-2 md:hidden" aria-label="Search">
          <SearchIcon />
        </button>
        {/* Nxeon: the real token balance + plans (components/cyrus-tokens; renders nothing outside the economy) */}
        <CyrusTokenChip compact beta={false} />
        <SoundToggle />
        <button
          type="button"
          onClick={() => setPanelOpen(!panelOpen)}
          className={`glass-soft grid h-9 w-9 place-items-center rounded-xl text-[16px] transition ${panelOpen ? "text-cy-accent" : "text-cy-ink-2 hover:text-cy-ink"}`}
          aria-label="Toggle preview panel"
          aria-pressed={panelOpen}
        >
          <PanelRightIcon />
        </button>
      </div>
    </header>
  );
}
