  useEffect(() => {
    const st = S.current;
    const first = st.nodes.size === 0;
    if (first) st.born = performance.now();
    const next = new Map<string, PNode>();
    for (const g of graph.nodes) {
      const prev = st.nodes.get(g.id);
      // Homes come from the saved layout when the user has dragged this branch before.
      const home = savedLayout[g.id];
      const hx = home?.[0] ?? g.hx;
      const hy = home?.[1] ?? g.hy;
      if (prev) {
        // Layout fields refresh (rows change as mods are added); physics state carries over.
        Object.assign(prev, { ...g, hx, hy, ink: inkOf(g.rgb) });
        next.set(g.id, prev);
        continue;
      }
      const parent = g.parent ? (next.get(g.parent) ?? st.nodes.get(g.parent)) : undefined;
      const px = parent?.x ?? 0;
      const py = parent?.y ?? 0;
      next.set(g.id, { ...g, hx, hy, x: px, y: py, vx: 0, vy: 0, rx: px, ry: py, ink: inkOf(g.rgb) });
    }
    st.nodes = next;
    st.order = graph.nodes.map((n) => next.get(n.id)!);
    st.links = graph.links.map((l) => ({ ...l, a: next.get(l.from)!, b: next.get(l.to)!, p: [0, 0, 0, 0, 0, 0, 0, 0] }));
    st.pairs = new Map();
    st.children = new Map();
    for (const l of st.links) {
      st.pairs.set(`${l.from}|${l.to}`, l);
      st.pairs.set(`${l.to}|${l.from}`, l);
      st.children.set(l.from, [...(st.children.get(l.from) ?? []), l.to]);
    }
    st.extent = layoutExtent(st.order);
    if (!st.follow) st.target.k = fitK();
  }, [graph, savedLayout, fitK]);

  /* ───────────── Node states (dimming) ───────────── */
  const nodeStates = useMemo(() => computeStates(graph.nodes, selection), [graph, selection]);
  useEffect(() => {
    S.current.states = nodeStates;
  /* ───────────── Pointer: drag branches, pan space ───────────── */
  const toWorld = (clientX: number, clientY: number) => {
    const st = S.current;
    const vc = { x: st.insets.l + (st.W - st.insets.l - st.insets.r) / 2, y: st.insets.t + (st.H - st.insets.t - st.insets.b) / 2 };
    return { x: (clientX - vc.x) / st.cam.k + st.cam.x, y: (clientY - vc.y) / st.cam.k + st.cam.y };
  };

  const selectNode = useCallback(
    (id: string) => {
      const n = S.current.nodes.get(id);
      if (!n) return;
      if (n.type === "core") select({ level: "core" });
      else if (n.ghost) useStore.getState().setAddGameOpen(true);
      else if (n.type === "game") select({ level: "game", gameId: n.gameId });
      else if (n.type === "category") select({ level: "category", gameId: n.gameId, category: n.category });
      else if (n.type === "mod" && n.idea) useStore.getState().pickIdea(n.modId!); // Nxeon: an idea writes its prompt
      else if (n.type === "mod") select({ level: "mod", gameId: n.gameId, category: n.category, modId: n.modId }, { openPanel: true });
      else {
