/** Built-in or user-added game by id. */
export function getGame(id: GameId | undefined): Game | undefined {
  if (!id) return undefined;
  return GAME_BY_ID[id] ?? useStore.getState().customGames.find((g) => g.id === id);
}

export function useGames(): Game[] {
  const custom = useStore((s) => s.customGames);
  return useMemo(() => [...GAMES, ...custom], [custom]);
}

export function useGame(id: GameId | undefined): Game | undefined {
  const games = useGames();
  return useMemo(() => (id ? games.find((g) => g.id === id) : undefined), [games, id]);
}
