export type NodeType = "core" | "game" | "category" | "mod" | "more";
export type Side = "left" | "right" | "up" | "down";

export interface LNode {
  id: string;
  type: NodeType;
  parent?: string;
  gameId?: GameId;
  category?: CyrusCategoryId;
  modId?: string;
