export const CORE_RGB = "167 139 250";
export const ADD_GAME_ID = "add-game";
export const VISIBLE_MODS = 3;
export const ROW_H = 30;
/** Radii of the round nodes, used for link endpoints. */
export const RADIUS = { core: 100, game: 54, add: 42, category: 28 } as const;

/**
 * Hand-placed layout, in the spirit of a mind map: five games around the core and a fan of
 * categories per game whose mod lists open away from the core. Extra categories (created by
 * forging into a new one) use the trailing slots.
 */
const LAYOUT: { pos: [number, number]; cats: [number, number, Side][] }[] = [
  { pos: [0, -215], cats: [[-235, -35, "left"], [0, -140, "right"], [235, -35, "right"], [-380, 40, "left"], [380, 40, "right"]] },
  { pos: [470, -30], cats: [[185, -125, "right"], [215, -5, "right"], [185, 115, "right"], [40, -190, "up"]] },
  { pos: [290, 205], cats: [[215, 0, "right"], [150, 110, "right"], [-35, 170, "right"], [0, 280, "down"]] },
  { pos: [-290, 205], cats: [[-215, 0, "left"], [-150, 110, "left"], [35, 170, "left"], [0, 280, "down"]] },
  { pos: [-470, -30], cats: [[-185, -125, "left"], [-215, -5, "left"], [-185, 115, "left"], [-40, -190, "up"]] },
];

/**
 * The six-game ring plus the "Add game" branch (last slot, top centre): two games across the top,
 * one on each side, two below, every category fanning away from the core.
 */
const LAYOUT7: { pos: [number, number]; cats: [number, number, Side][] }[] = [
  { pos: [-360, -205], cats: [[-225, -70, "left"], [-80, -160, "left"], [-215, 75, "left"], [-350, 0, "left"], [60, -175, "up"]] },
  { pos: [360, -205], cats: [[225, -70, "right"], [80, -160, "right"], [215, 75, "right"], [350, 0, "right"], [-60, -175, "up"]] },
  { pos: [600, 30], cats: [[195, -100, "right"], [215, 25, "right"], [190, 150, "right"], [40, -175, "up"], [40, 205, "down"]] },
  { pos: [330, 245], cats: [[215, 0, "right"], [150, 110, "right"], [-35, 170, "right"], [0, 280, "down"]] },
  { pos: [-330, 245], cats: [[-215, 0, "left"], [-150, 110, "left"], [35, 170, "left"], [0, 280, "down"]] },
  { pos: [-600, 30], cats: [[-195, -100, "left"], [-215, 25, "left"], [-190, 150, "left"], [-40, -175, "up"], [-40, 205, "down"]] },
  { pos: [0, -265], cats: [] },
];

function hash(s: string) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return (h >>> 0) / 4294967295;
}

/** Where pill `row` of a list sits, relative to its category's centre. */
export function pillOffset(side: Side, row: number, rows: number): [number, number] {
  if (side === "left") return [-78, (row - (rows - 1) / 2) * ROW_H];
  if (side === "right") return [78, (row - (rows - 1) / 2) * ROW_H];
  if (side === "up") return [0, -(60 + (rows - 1 - row) * ROW_H)];
  return [0, 60 + row * ROW_H];
}

/**
 * Slot for game `gi` of `n`. Five games use the hand-tuned mind-map layout; any other count is
 * spread evenly on a wide ellipse (starting upper-right so nothing sits under the prompt dock).
 */
function slotFor(gi: number, n: number) {
  if (n === LAYOUT.length) return LAYOUT[gi];
  if (n === LAYOUT7.length) return LAYOUT7[gi];
  const start = n % 2 === 0 ? -90 + 180 / n : -90;
  const th = ((start + (gi * 360) / n) * Math.PI) / 180;
  const rx = 470 + Math.max(0, n - 5) * 35;
  const ry = 235 + Math.max(0, n - 5) * 12;
  const pos: [number, number] = [Math.round(Math.cos(th) * rx), Math.round(Math.sin(th) * ry)];
  const cats = [-0.85, 0, 0.85, -1.5, 1.5].map((d): [number, number, Side] => {
    const a = th + d;
    const cx = Math.round(Math.cos(a) * 225);
    const cy = Math.round(Math.sin(a) * 150);
    const ax = pos[0] + cx;
    const side: Side = Math.abs(ax) < 120 ? (pos[1] + cy < 0 ? "up" : "down") : ax < 0 ? "left" : "right";
    return [cx, cy, side];
  });
  return { pos, cats };

  return { pos, cats };
}

/** `withAdd` appends the empty "Add game" branch after the games (while there's room for more). */
export function buildGraph(mods: Mod[], games: Game[], withAdd = false) {
  const slots = games.length + (withAdd ? 1 : 0);
  const nodes: LNode[] = [];
  const links: LLink[] = [];
  const base = { phase: 0, hx: 0, hy: 0, side: "right" as Side, row: 0, rows: 0, hidden: 0 };
  nodes.push({ ...base, id: CORE_ID, type: "core", rgb: CORE_RGB, label: "Cyrus" });

  games.forEach((game, gi) => {
    const slot = slotFor(gi, slots);
    const gameMods = mods.filter((m) => m.gameId === game.id);
    nodes.push({
      ...base,
      id: game.id,
      type: "game",
      parent: CORE_ID,
      gameId: game.id,
      rgb: game.rgb,
      label: game.name,
      emblem: game.emblem,
      logo: game.logo,
      logoTone: game.logoTone,
      short: game.short,
      soon: !gameIsLive(game),
      phase: hash(game.id) * Math.PI * 2,
      hx: slot.pos[0],
      hy: slot.pos[1],
    });
    links.push({ id: `${CORE_ID}>${game.id}`, from: CORE_ID, to: game.id, kind: "game" });

    const cats = [...game.categories];
    for (const m of gameMods) if (!cats.includes(m.category)) cats.push(m.category);

    cats.forEach((key, ci) => {
      const cid = categoryNodeId(game.id, key);
      const [cx, cy, side] =
        slot.cats[ci] ?? ([Math.cos(ci) * 330, Math.sin(ci) * 330, Math.cos(ci) < 0 ? "left" : "right"] as [number, number, Side]);
      nodes.push({
        ...base,
        id: cid,
        type: "category",
        parent: game.id,
        gameId: game.id,
        category: key,
        rgb: game.rgb,
        label: CATEGORY_BY_KEY[key].label,
        phase: hash(cid) * Math.PI * 2,
        hx: cx,
        hy: cy,
        side,
      });
      links.push({ id: `${game.id}>${cid}`, from: game.id, to: cid, kind: "category" });

      // Newest first, so a freshly forged mod always shows in the list.
      const catMods = gameMods.filter((m) => m.category === key).sort((a, b) => b.createdAt - a.createdAt);
      const shown = catMods.slice(0, VISIBLE_MODS);
      const rows = shown.length + 1;
      shown.forEach((m, row) => {
        nodes.push({ ...base, id: m.id, type: "mod", parent: cid, gameId: game.id, category: key, modId: m.id, rgb: game.rgb, label: m.name, side, row, rows, idea: m.idea, failed: m.real?.failed, library: !!m.library });
        links.push({ id: `${cid}>${m.id}`, from: cid, to: m.id, kind: "mod" });
      });
      const moreId = `${cid}:more`;
      nodes.push({
        ...base,
        id: moreId,
        type: "more",
        parent: cid,
        gameId: game.id,
        category: key,
        rgb: game.rgb,
        // an empty branch says so honestly: "Forge new" where Cyrus builds, "Coming soon" elsewhere
        label: catMods.length > VISIBLE_MODS ? `+${catMods.length - VISIBLE_MODS} more` : catMods.length || gameIsLive(game) ? "Forge new" : "Coming soon",
        side,
        row: rows - 1,
        rows,
        hidden: Math.max(0, catMods.length - VISIBLE_MODS),
      });
    });
  });

  if (withAdd) {
    const slot = slotFor(games.length, slots);
    nodes.push({
      ...base,
      id: ADD_GAME_ID,
      type: "game",
      parent: CORE_ID,
      ghost: true,
      rgb: CORE_RGB,
      label: "Add game",
      short: "Add game",
      phase: hash(ADD_GAME_ID) * Math.PI * 2,
      hx: slot.pos[0],
      hy: slot.pos[1],
    });
    links.push({ id: `${CORE_ID}>${ADD_GAME_ID}`, from: CORE_ID, to: ADD_GAME_ID, kind: "game" });
  }

