  return { nodes, links };
}

interface Box {
  x0: number;
  x1: number;
  y0: number;
  y1: number;
}

/** How far `a` must move to stop overlapping `b` (along the cheaper axis), or null if clear. */
function separation(a: Box, b: Box, pad = 6): [number, number] | null {
  const ox = Math.min(a.x1, b.x1) - Math.max(a.x0, b.x0);
  const oy = Math.min(a.y1, b.y1) - Math.max(a.y0, b.y0);
  if (ox <= 0 || oy <= 0) return null;
  const acx = (a.x0 + a.x1) / 2;
  const bcx = (b.x0 + b.x1) / 2;
  const acy = (a.y0 + a.y1) / 2;
  const bcy = (b.y0 + b.y1) / 2;
  if (ox < oy) return [(acx < bcx ? -1 : 1) * (ox + pad), 0];
  return [0, (acy < bcy ? -1 : 1) * (oy + pad)];
}

