  const fixed: Box[] = [
    { x0: -132, x1: 132, y0: -132, y1: 150 },
    ...games.map((g) => ({ x0: g.hx - 62, x1: g.hx + 62, y0: g.hy - 62, y1: g.hy + 78 })),
  ];
  for (let it = 0; it < 90; it++) {
    let moved = false;
    for (let i = 0; i < cats.length; i++) {
      const pi = pos.get(cats[i].id)!;
      for (const f of fixed) {
        const d = separation(boxOf(cats[i]), f);
        if (d) {
          pi.x += d[0];
          pi.y += d[1];
          moved = true;
        }
      }
      for (let j = i + 1; j < cats.length; j++) {
        const d = separation(boxOf(cats[i]), boxOf(cats[j]));
        if (!d) continue;
        const pj = pos.get(cats[j].id)!;
        pi.x += d[0] / 2;
        pi.y += d[1] / 2;
        pj.x -= d[0] / 2;
        pj.y -= d[1] / 2;
        moved = true;
      }
    }
    if (!moved) break;
  }
  for (const c of cats) {
    const g = gameById.get(c.parent!)!;
    const p = pos.get(c.id)!;
    c.hx = Math.round(p.x - g.hx);
    c.hy = Math.round(p.y - g.hy);
  }
}

/** Half-extents of the whole layout at rest, for fitting the overview camera. */
export function layoutExtent(nodes: LNode[]) {
  const byId = new Map(nodes.map((n) => [n.id, n]));
  let halfW = 260;
  let halfH = 260;
  for (const n of nodes) {
    if (n.type !== "category") continue;
    const g = byId.get(n.parent!)!;
    const x = g.hx + n.hx;
    const y = g.hy + n.hy;
    const rows = nodes.filter((m) => m.parent === n.id).length;
    if (n.side === "left" || n.side === "right") {
      halfW = Math.max(halfW, Math.abs(x) + 78 + 185);
      halfH = Math.max(halfH, Math.abs(y) + (rows * ROW_H) / 2 + 10);
    } else {
      halfW = Math.max(halfW, Math.abs(x) + 110);
      halfH = Math.max(halfH, Math.abs(y) + 60 + rows * ROW_H);
    }
  }
  return { halfW, halfH };
}

export type NodeState = "on" | "near" | "off";

export function selectedNodeId(sel: Selection): string {
  if (sel.level === "mod" && sel.modId) return sel.modId;
  if (sel.level === "category" && sel.gameId && sel.category) return categoryNodeId(sel.gameId, sel.category);
  if (sel.level === "game" && sel.gameId) return sel.gameId;
  return CORE_ID;
}

/** Dims everything outside the branch you've jumped into. */
export function computeStates(nodes: LNode[], sel: Selection): Map<string, NodeState> {
  const state = new Map<string, NodeState>();
  for (const n of nodes) {
    if (sel.level === "core" || n.type === "core") {
      state.set(n.id, "on");
      continue;
    }
    const sameGame = n.gameId === sel.gameId;
    const sameCat = sameGame && n.category === sel.category;
    let s: NodeState = "off";
    if (sel.level === "game") s = sameGame ? "on" : "off";
    else if (n.type === "game") s = sameGame ? "on" : "off";
    else if (n.type === "category") s = sameCat ? "on" : sameGame ? "near" : "off";
    else if (sel.level === "category") s = sameCat ? "on" : sameGame ? "near" : "off";
    else s = n.id === sel.modId || (sameCat && n.type === "more") ? "on" : sameCat ? "near" : sameGame ? "near" : "off";
    state.set(n.id, s);
  }
  return state;
}

