      {/* Aurora curtains on a parallax layer larger than the screen: it pans and zooms with the
          network at a slower rate, as if it's further away. */}
      <div ref={layerRef} className="aurora-layer" />

      <canvas ref={canvasRef} className="absolute inset-0" />
      <div className="vignette" />
    </div>
  );
}
