// Cyrus notifications (r40), SERVER ONLY: the ONE way Cyrus tells a person something (build finished, install result,
// mod outdated, takedown, low tokens). In-app rows in Cyrus' own table (the bell), email through the host's mail stack
// (host.mail: Nxeon's mailer) from the cyrus.my sender. HOST SEAM: no Nxeon imports.
//
// Fail closed, never throws into the caller (a notification must never break a build, an install or a takedown):
//   CYRUS_NOTIFY != "1"              -> nothing recorded, nothing sent
//   tables not migrated              -> nothing recorded (logged once per call)
//   duplicate (user, event, ref)     -> nothing new (idempotent: a re-run of a sweep notifies once)
//   email needs CYRUS_NOTIFY_EMAIL=1 + a valid cyrus.my sender (setting cyrus_mail_from) + host.mail + the person's
//   preference (takedown email cannot be turned off); the row records "sent" / "skipped:<why>" / "failed".
import { randomBytes } from "node:crypto";
import { cyrusDb as db } from "../db";
import { getHost } from "../host";
import { MAIL_FROM_SETTING, notifyEmailEnabled, notifyEnabled, parsePrefs, refFor, validCyrusSender, wants, type NotifyEvent, type Prefs } from "./events";
import { renderNotification } from "./templates";

type Env = Record<string, string | undefined>;
const appBase = (env: Env) => (env.CYRUS_PUBLIC_BASE || env.APP_URL || "https://nxeon.cloud").replace(/\/$/, "");
export const PREFS_PATH = "/dashboard/cyrus/notifications";

export async function loadPrefs(userId: string): Promise<Prefs> {
  const row = await db.cyrusNotificationPref.findUnique({ where: { userId } }).catch(() => null);
  return parsePrefs(row?.prefs ?? null);
}

export async function savePrefs(userId: string, prefs: Prefs): Promise<boolean> {
  try {
    await db.cyrusNotificationPref.upsert({ where: { userId }, update: { prefs: prefs as never }, create: { userId, prefs: prefs as never } });
    return true;
  } catch { return false; }
}

export type NotifyOutcome = { recorded: boolean; email: string | null; reason?: string };

export async function notify(userId: string, event: NotifyEvent, data: Record<string, unknown>, env: Env = process.env): Promise<NotifyOutcome> {
  if (!notifyEnabled(env)) return { recorded: false, email: null, reason: "off" };
  try {
    const prefs = await loadPrefs(userId);
    const ref = refFor(event, data).slice(0, 200);
    const base = appBase(env);
    const r = renderNotification(event, data, { appBase: base, prefsUrl: `${base}${PREFS_PATH}` });
    const inApp = wants(prefs, event, "inApp");
    const id = `cn_${randomBytes(10).toString("hex")}`;
    try {
      // the in-app row is also the dedupe record, so it is written even when the bell is off for this event (readAt set)
      await db.cyrusNotification.create({ data: { id, userId, event, ref, title: r.title, body: r.body, href: r.href, data: data as never, readAt: inApp ? null : new Date() } });
    } catch (e) {
      const code = (e as { code?: string }).code;
      return { recorded: false, email: null, reason: code === "P2002" ? "duplicate" : "store_unavailable" };
    }

// Cyrus notifications (r40): the bell's data. GET -> { unread, items[] } for the signed-in Cyrus user; POST { id } or
// { all: true } marks read. 404 unless CYRUS_NOTIFY=1 and the Cyrus access rule passes (never while impersonating).
// Same-origin only for POST (the session cookie is SameSite=Lax; this blocks cross-site form posts as well).
import { getHost } from "@/lib/cyrus/host";
import { notifyEnabled } from "@/lib/cyrus/notify/events";
import { listNotifications, markRead, unreadCount } from "@/lib/cyrus/notify";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const json = (status: number, body: unknown) => new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json", "cache-control": "no-store" } });

async function viewer() {
  if (!notifyEnabled()) return null;
  return getHost().builds.accessUser().catch(() => null);
}

export async function GET() {
  const u = await viewer();
  if (!u) return json(404, { error: "Not found" });
  const [items, unread] = await Promise.all([listNotifications(u.id, 30), unreadCount(u.id)]);
  return json(200, { unread, items: items ?? [], available: items !== null });
}

export async function POST(req: Request) {
  const u = await viewer();
  if (!u) return json(404, { error: "Not found" });
  const origin = req.headers.get("origin");
  if (origin && origin !== new URL(req.url).origin) return json(403, { error: "cross-site" });
  let b: { id?: unknown; all?: unknown } = {};
  try { b = (await req.json()) as typeof b; } catch { return json(400, { error: "bad json" }); }
  const id = b.all === true ? "all" : typeof b.id === "string" && /^cn_[0-9a-f]{20}$/.test(b.id) ? b.id : null;
  if (!id) return json(400, { error: "send { id } or { all: true }" });
  return json(200, { marked: await markRead(u.id, id) });
}
