export async function CyrusPage(selectedId: string | null, opts: { retarget?: string | null; tab?: string | null; server?: string | null; file?: string | null } = {}) {
  const user = await requireModBuilderUser();
  const [rows, health, servers, studios] = await Promise.all([
    cyrusDb.modBuild.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" }, take: 200 }),
