  return <><h1 className="sr-only">Cyrus studio</h1><CyrusApp initialBuilds={fresh.map(toView)} servers={servers} online={!!health?.ok} userId={user.id} selectedId={selectedId} retarget={opts.retarget && (MB_VERSIONS as readonly string[]).includes(opts.retarget) ? opts.retarget : null} studios={studios} partStudios={studios ? await studioSwitches().catch(() => OFF) : OFF} tab={opts.tab === "assets" ? (studios ? "assets" : null) : opts.tab && PANEL_TABS.includes(opts.tab as PanelTab) ? (opts.tab as PanelTab) : null} file={opts.file && /^src\/main\/[A-Za-z0-9_./-]{1,200}$/.test(opts.file) && !opts.file.includes("..") ? opts.file : null} serverContext={serverContext} /></>;
}

