// Cyrus core studio preferences (feature/cyrus-studio-ux), PURE: no Nxeon imports, safe in client and server code.
// One additive row per person (CyrusStudioPref.prefs):
//   layout  where the person dragged each branch: id -> [dx, dy] offset from its parent (games from the core, categories
//           from their game, individual mod pills from their category's list slot)
//   simple  the studio's Simple view (a flat list of the same mods and the same prompt dock; nothing is removed)
//   more    per category, how many mods the person has chosen to show beyond the default fan ("Load more")
// Everything read from storage or the wire goes through parseStudioPrefs: unknown keys dropped, numbers clamped, sizes capped.

export type StudioPrefs = {
  v: 1;
  layout: Record<string, [number, number]>;
  simple: boolean;
  more: Record<string, number>;
};

export const EMPTY_PREFS: StudioPrefs = { v: 1, layout: {}, simple: false, more: {} };
export const MAX_LAYOUT_ENTRIES = 2000;
export const MAX_ID_LEN = 160;
export const MAX_OFFSET = 6000;
/** Mods shown per page in a category fan, and the most one fan may ever grow to. */
export const PAGE_SIZE = 6;
export const MAX_SHOWN = 120;

const clampOff = (n: number) => Math.max(-MAX_OFFSET, Math.min(MAX_OFFSET, Math.round(n)));

export function parseStudioPrefs(raw: unknown): StudioPrefs {
  const o = raw && typeof raw === "object" && !Array.isArray(raw) ? (raw as Record<string, unknown>) : {};
  const layout: StudioPrefs["layout"] = {};
  const lay = o.layout && typeof o.layout === "object" && !Array.isArray(o.layout) ? (o.layout as Record<string, unknown>) : {};
  let n = 0;
  for (const [k, v] of Object.entries(lay)) {
    if (n >= MAX_LAYOUT_ENTRIES) break;
    if (!k || k.length > MAX_ID_LEN || k === "__proto__" || k === "constructor") continue;
    if (!Array.isArray(v) || v.length !== 2 || typeof v[0] !== "number" || typeof v[1] !== "number" || !Number.isFinite(v[0]) || !Number.isFinite(v[1])) continue;
    layout[k] = [clampOff(v[0]), clampOff(v[1])];
    n++;
  }
  const more: StudioPrefs["more"] = {};
  const mo = o.more && typeof o.more === "object" && !Array.isArray(o.more) ? (o.more as Record<string, unknown>) : {};
  n = 0;
  for (const [k, v] of Object.entries(mo)) {
    if (n >= 400) break;
    if (!k || k.length > MAX_ID_LEN || k === "__proto__" || k === "constructor") continue;
    if (typeof v !== "number" || !Number.isFinite(v)) continue;
    const c = Math.max(0, Math.min(MAX_SHOWN, Math.round(v)));
    if (c > 0) { more[k] = c; n++; }
  }
  return { v: 1, layout, simple: o.simple === true, more };
}

/** How many mods a category fan shows: the default plus the person's "Load more" pages, capped. */
export function shownCount(base: number, extra: number | undefined, total: number): number {
  return Math.max(0, Math.min(total, MAX_SHOWN, base + Math.max(0, extra ?? 0)));
}

/** Next page size for "Load more": a fixed page, never more than what is left. */
export function nextMore(current: number | undefined, base: number, total: number): number {
  const shown = shownCount(base, current, total);
  return Math.min(Math.max(0, total - base), Math.min(MAX_SHOWN - base, shown - base + PAGE_SIZE));
}

/** Merge a patch of changed keys onto stored prefs: layout entries set or (null) removed, flags replaced. */
export function applyPatch(base: StudioPrefs, patch: { layout?: Record<string, [number, number] | null>; simple?: boolean; more?: Record<string, number | null> }): StudioPrefs {
  const layout = { ...base.layout };
  for (const [k, v] of Object.entries(patch.layout ?? {})) { if (v === null) delete layout[k]; else layout[k] = v; }
  const more = { ...base.more };
  for (const [k, v] of Object.entries(patch.more ?? {})) { if (v === null || v <= 0) delete more[k]; else more[k] = v; }
  return parseStudioPrefs({ v: 1, layout, simple: patch.simple ?? base.simple, more });
}
