// view switch and per-category "Load more" counts, saved to their profile so they follow them across browsers and hosts
// (nxeon.cloud/dashboard/cyrus and cyrus.my/studio share this route).
//   GET  -> { prefs, stored }
//   POST { layout?: {id: [dx,dy]|null}, simple?: boolean, more?: {id: n|null} }  -> { prefs, saved }   (a PATCH: only the keys sent change)
// Same access rule as the studio itself; same-origin only for writes. Fails soft: until the table exists `saved` is false and
// the studio keeps the data in the browser.
import { getHost } from "@/lib/cyrus/host";
import { applyPatch, MAX_ID_LEN, MAX_LAYOUT_ENTRIES } from "@/lib/cyrus/studio-prefs";
import { loadStudioPrefs, saveStudioPrefs } from "@/lib/cyrus/studio-prefs/store.server";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const json = (status: number, body: unknown) => new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json", "cache-control": "no-store" } });

export async function GET() {
  const u = await getHost().builds.accessUser().catch(() => null);
  if (!u) return json(404, { error: "Not found" });
  return json(200, await loadStudioPrefs(u.id));
}

export async function POST(req: Request) {
  const u = await getHost().builds.accessUser().catch(() => null);
  if (!u) return json(404, { error: "Not found" });
  const origin = req.headers.get("origin");
  if (origin && origin !== new URL(req.url).origin) return json(403, { error: "cross-site" });
  let b: { layout?: unknown; simple?: unknown; more?: unknown } = {};
  try { b = (await req.json()) as typeof b; } catch { return json(400, { error: "bad json" }); }
  const patch: Parameters<typeof applyPatch>[1] = {};
  const isObj = (x: unknown): x is Record<string, unknown> => !!x && typeof x === "object" && !Array.isArray(x);
  if (b.layout !== undefined) {
    if (!isObj(b.layout) || Object.keys(b.layout).length > MAX_LAYOUT_ENTRIES) return json(400, { error: "layout" });
    const out: Record<string, [number, number] | null> = {};
    for (const [k, v] of Object.entries(b.layout)) {
      if (!k || k.length > MAX_ID_LEN) continue;
      if (v === null) out[k] = null;
      else if (Array.isArray(v) && v.length === 2 && typeof v[0] === "number" && typeof v[1] === "number" && Number.isFinite(v[0]) && Number.isFinite(v[1])) out[k] = [v[0], v[1]];
    }
    patch.layout = out;
  }
  if (b.simple !== undefined) { if (typeof b.simple !== "boolean") return json(400, { error: "simple" }); patch.simple = b.simple; }
  if (b.more !== undefined) {
    if (!isObj(b.more) || Object.keys(b.more).length > 400) return json(400, { error: "more" });
    const out: Record<string, number | null> = {};
    for (const [k, v] of Object.entries(b.more)) { if (!k || k.length > MAX_ID_LEN) continue; if (v === null) out[k] = null; else if (typeof v === "number" && Number.isFinite(v)) out[k] = v; }
    patch.more = out;
  }
  const cur = await loadStudioPrefs(u.id);
  const next = applyPatch(cur.prefs, patch);
  const saved = await saveStudioPrefs(u.id, next);
  return json(200, { prefs: next, saved });
}
