18:import {

import {
  CORE_RGB,
  RADIUS,
  buildGraph,
  computeStates,
  layoutExtent,
  pillOffset,
  selectedNodeId,
  type LLink,
  type LNode,
  type NodeState,
} from "./graph";

/** A node with live physics state. */
type PNode = LNode & { x: number; y: number; vx: number; vy: number; rx: number; ry: number; ink: string };
/** A link with its current cubic curve. */
type PLink = LLink & { a: PNode; b: PNode; p: number[] };

interface Packet {
  path: string[];
  seg: number;
  t: number;
  speed: number;
